 "content": "def transform(grid):
    """Project a three-color seed bar toward matching endpoint markers."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Locate the contiguous three-color seed bar.
    seed = None
    for r, row in enumerate(grid):
        for c in range(w - 2):
            if row[c] and row[c + 1] and row[c + 2]:
                seed = (r, c, row[c], row[c + 1], row[c + 2])
                break
        if seed:
            break
    if seed is None:
        return out

    r0, c0, first, middle, last = seed
    first_markers = [(r, c) for r in range(h) for c in range(w)
                     if grid[r][c] == first and not (r == r0 and c == c0)]
    last_markers = [(r, c) for r in range(h) for c in range(w)
                    if grid[r][c] == last and not (r == r0 and c == c0 + 2)]

    # The first-color marker defines an L from the first seed cell.
    if first_markers:
        rm, cm = first_markers[0]
        for r in range(min(r0, rm), max(r0, rm) + 1):
            out[r][c0] = first
        for c in range(min(c0, cm), max(c0, cm) + 1):
            out[rm][c] = first

    # Middle seed color continues vertically downward to the grid edge.
    for r in range(r0, h):
        out[r][c0 + 1] = middle

    # The last-color marker carries the seed bar across its row, extending
    # the final color from the last seed cell to the marker.
    if last_markers:
        rm, cm = last_markers[0]
        for j, color in enumerate((first, middle, last)):
            out[rm][c0 + j] = color
        for c in range(c0 + 2, cm + 1):
            out[rm][c] = last

    return out
